INSERT INTO public.dataset_records VALUES (318, '“Global warming and climate change, even if it is 100% caused by humans, is so slow that it cannot be observed by anyone in their lifetime.', '“Global warming and climate change, even if it is 100% caused by humans, is so slow that it cannot be observed by anyone in their lifetime.', 'FAKE', 'Climate Change', 'climate-fever-enriched');
