INSERT INTO public.dataset_records VALUES (331, 'Global warming is driving major melting on the surface of Greenland’s glaciers and is speeding up their travel into the sea.”', 'Global warming is driving major melting on the surface of Greenland’s glaciers and is speeding up their travel into the sea.”', 'REAL', 'Climate Change', 'climate-fever-enriched');
INSERT INTO public.dataset_records VALUES (332, 'The melting Greenland ice sheet is already a major contributor to rising sea level and if it was eventually lost entirely, the oceans would rise by six metres around the world, flooding many of the world’s largest cities.', 'The melting Greenland ice sheet is already a major contributor to rising sea level and if it was eventually lost entirely, the oceans would rise by six metres around the world, flooding many of the world’s largest cities.', 'REAL', 'Climate Change', 'climate-fever-enriched');
