INSERT INTO public.dataset_records VALUES (334, '“During ice ages, caused by wobbles in the Earth’s orbit, sea levels dropped more than 400 feet as ice piled up on land.', '“During ice ages, caused by wobbles in the Earth’s orbit, sea levels dropped more than 400 feet as ice piled up on land.', 'REAL', 'Climate Change', 'climate-fever-enriched');
