INSERT INTO public.dataset_records VALUES (647, 'Some global warming ''skeptics'' argue that the Earth''s climate sensitivity is so low that a doubling of atmospheric CO2 will result in a surface temperature change on the order of 1°C or less, and that therefore global warming is nothing to worry about.', 'Some global warming ''skeptics'' argue that the Earth''s climate sensitivity is so low that a doubling of atmospheric CO2 will result in a surface temperature change on the order of 1°C or less, and that therefore global warming is nothing to worry about.', 'FAKE', 'Climate Change', 'climate-fever-enriched');
