INSERT INTO public.dataset_records VALUES (652, 'Since the hockey stick paper in 1998, there have been a number of proxy studies analysing a variety of different sources including corals, stalagmites, tree rings, boreholes and ice cores.', 'Since the hockey stick paper in 1998, there have been a number of proxy studies analysing a variety of different sources including corals, stalagmites, tree rings, boreholes and ice cores.', 'REAL', 'Biodiversity', 'climate-fever-enriched');
