INSERT INTO public.dataset_records VALUES (654, 'A number of independent investigations from different countries, universities and government bodies have investigated the stolen emails and found no evidence of wrong doing.', 'A number of independent investigations from different countries, universities and government bodies have investigated the stolen emails and found no evidence of wrong doing.', 'REAL', 'Climate Change', 'climate-fever-enriched');
INSERT INTO public.dataset_records VALUES (655, 'Focusing on a few suggestive emails, taken out of context, merely serves to distract from the wealth of empirical evidence for man-made global warming.', 'Focusing on a few suggestive emails, taken out of context, merely serves to distract from the wealth of empirical evidence for man-made global warming.', 'REAL', 'Climate Change', 'climate-fever-enriched');
INSERT INTO public.dataset_records VALUES (656, '“[T]he 1079 emails and 72 documents seem indeed evidence of a scandal  involving most of the most prominent scientists pushing the man-made  warming theory - a scandal that is one of the greatest in modern  science.', '“[T]he 1079 emails and 72 documents seem indeed evidence of a scandal involving most of the most prominent scientists pushing the man-made warming theory - a scandal that is one of the greatest in modern science.', 'REAL', 'Climate Change', 'climate-fever-enriched');
