INSERT INTO public.dataset_records VALUES (726, 'In fact, the rate of increase from September onward is the fastest rate of change on record, either upwards or downwards.', 'In fact, the rate of increase from September onward is the fastest rate of change on record, either upwards or downwards.', 'FAKE', 'Climate Change', 'climate-fever-enriched');
INSERT INTO public.dataset_records VALUES (727, 'Together, these two unaltered [sea level] datasets indicate that global mean sea level trend has remained stable over the entire period 1992-2007, altogether eliminating the apparent 3.2 mm/year rate of sea-level rise arising from the “adjusted” data.', 'Together, these two unaltered [sea level] datasets indicate that global mean sea level trend has remained stable over the entire period 1992-2007, altogether eliminating the apparent 3.2 mm/year rate of sea-level rise arising from the “adjusted” data.', 'FAKE', 'Climate Change', 'climate-fever-enriched');
INSERT INTO public.dataset_records VALUES (728, '''The UN’s Intergovernmental Panel on Climate Change misled the press and public into believing that thousands of scientists backed its claims on manmade global warming, according to Mike Hulme, a prominent climate scientist and IPCC insider.', '''The UN’s Intergovernmental Panel on Climate Change misled the press and public into believing that thousands of scientists backed its claims on manmade global warming, according to Mike Hulme, a prominent climate scientist and IPCC insider.', 'FAKE', 'Climate Change', 'climate-fever-enriched');
