INSERT INTO public.dataset_records VALUES (730, 'The report suggests significantly smaller overall  ice-mass losses than previous estimates.', 'The report suggests significantly smaller overall ice-mass losses than previous estimates.', 'FAKE', 'Climate Change', 'climate-fever-enriched');
