INSERT INTO public.dataset_records VALUES (733, '"Global warming data apparently cooked by U.S. government-funded body  shows astounding temperature fraud with increases averaging 10 to 15  degrees Fahrenheit.', '"Global warming data apparently cooked by U.S. government-funded body shows astounding temperature fraud with increases averaging 10 to 15 degrees Fahrenheit.', 'FAKE', 'Climate Change', 'climate-fever-enriched');
INSERT INTO public.dataset_records VALUES (734, 'Claims have recently surfaced in the blogosphere that an increasing number of scientists are warning of an imminent global cooling, some even going so far as to call it a "growing consensus".', 'Claims have recently surfaced in the blogosphere that an increasing number of scientists are warning of an imminent global cooling, some even going so far as to call it a "growing consensus".', 'FAKE', 'Climate Change', 'climate-fever-enriched');
INSERT INTO public.dataset_records VALUES (735, 'Rather than 100 years of unprecedented global warming as predicted by  IPCC, the global temperatures have leveled off and we seem to be heading  for cooler weather."', 'Rather than 100 years of unprecedented global warming as predicted by IPCC, the global temperatures have leveled off and we seem to be heading for cooler weather."', 'FAKE', 'Climate Change', 'climate-fever-enriched');
